document.addEventListener('DOMContentLoaded', () => {
  const root = document.getElementById('foldable-tester-root');
  if (!root) return;

  // Elements
  const valPostureState = document.getElementById('val-posture-state');
  const valPostureSub = document.getElementById('val-posture-sub');
  const valSegmentsCount = document.getElementById('val-segments-count');
  const valSegmentsSub = document.getElementById('val-segments-sub');
  const valTouchScore = document.getElementById('val-touch-score');
  const valTouchSub = document.getElementById('val-touch-sub');

  const schematic = document.getElementById('screen-schematic');
  const paneA = document.getElementById('pane-a');
  const paneB = document.getElementById('pane-b');
  const creaseDivider = document.getElementById('crease-divider');
  const dimPaneA = document.getElementById('dim-pane-a');
  const dimPaneB = document.getElementById('dim-pane-b');

  const btnSimFlat = document.getElementById('btn-sim-flat');
  const btnSimBook = document.getElementById('btn-sim-book');
  const btnSimLaptop = document.getElementById('btn-sim-laptop');

  const canvas = document.getElementById('crease-canvas');
  const btnClear = document.getElementById('btn-clear-canvas');
  const statTraversals = document.getElementById('stat-traversals');
  const statMaxJump = document.getElementById('stat-max-jump');

  // 1. Check Device Posture API
  function updatePosture() {
    if (navigator.devicePosture) {
      const p = navigator.devicePosture.type;
      valPostureState.textContent = p === 'folded' ? 'Folded Posture' : 'Continuous Posture';
      valPostureState.className = p === 'folded' ? 'text-2xl font-black text-amber-600 pt-1' : 'text-2xl font-black text-emerald-600 pt-1';
      valPostureSub.textContent = `Physical hinge active: ${p}`;
    } else {
      const isFoldedMq = window.matchMedia && window.matchMedia('(device-posture: folded)').matches;
      if (isFoldedMq) {
        valPostureState.textContent = 'Folded (CSS MQ)';
        valPostureState.className = 'text-2xl font-black text-amber-600 pt-1';
        valPostureSub.textContent = '@media (device-posture: folded) active';
      } else {
        valPostureState.textContent = 'Continuous / Planar';
        valPostureState.className = 'text-2xl font-black text-slate-800 pt-1';
        valPostureSub.textContent = 'Standard flat screen or API idle';
      }
    }
  }
  updatePosture();
  if (navigator.devicePosture && navigator.devicePosture.addEventListener) {
    navigator.devicePosture.addEventListener('change', updatePosture);
  }

  // 2. Viewport Segments
  function updateSegments() {
    // Check if CSS environment variables exist
    const rootStyle = getComputedStyle(document.documentElement);
    const seg0w = rootStyle.getPropertyValue('env(viewport-segment-width 0 0)') || '';
    if (seg0w) {
      valSegmentsCount.textContent = '2 Segments Detected';
      valSegmentsSub.textContent = 'Active dual-segment display layout';
    } else {
      valSegmentsCount.textContent = '1 Unified Segment';
      valSegmentsSub.textContent = 'Standard single-viewport viewport';
    }
  }
  updateSegments();

  // 3. Posture Simulator Buttons
  function setSimMode(mode) {
    btnSimFlat.className = 'px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ' + (mode === 'flat' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200');
    btnSimBook.className = 'px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ' + (mode === 'book' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200');
    btnSimLaptop.className = 'px-3 py-1.5 rounded-lg text-xs font-bold transition-colors ' + (mode === 'laptop' ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-700 hover:bg-slate-200');

    if (mode === 'flat') {
      schematic.className = 'relative w-full max-w-2xl mx-auto h-72 rounded-2xl border-2 border-slate-300 bg-slate-900 p-3 shadow-inner flex flex-row overflow-hidden text-white font-mono text-xs';
      creaseDivider.style.display = 'none';
      paneA.className = 'flex-1 bg-slate-800/90 rounded-xl p-4 flex flex-col justify-between border border-slate-700';
      paneB.className = 'hidden';
      dimPaneA.textContent = `${schematic.clientWidth} x 288 px`;
    } else if (mode === 'book') {
      schematic.className = 'relative w-full max-w-2xl mx-auto h-72 rounded-2xl border-2 border-slate-300 bg-slate-900 p-3 shadow-inner flex flex-row overflow-hidden text-white font-mono text-xs';
      creaseDivider.style.display = 'flex';
      creaseDivider.className = 'w-6 bg-gradient-to-r from-slate-950 via-slate-700 to-slate-950 border-x border-slate-600 flex items-center justify-center relative cursor-col-resize';
      paneA.className = 'flex-1 bg-slate-800/90 rounded-xl p-4 flex flex-col justify-between border border-slate-700';
      paneB.className = 'flex-1 bg-slate-800/90 rounded-xl p-4 flex flex-col justify-between border border-slate-700';
      const halfW = Math.round((schematic.clientWidth - 24) / 2);
      dimPaneA.textContent = `${halfW} x 288 px`;
      dimPaneB.textContent = `${halfW} x 288 px`;
    } else if (mode === 'laptop') {
      schematic.className = 'relative w-full max-w-2xl mx-auto h-72 rounded-2xl border-2 border-slate-300 bg-slate-900 p-3 shadow-inner flex flex-col overflow-hidden text-white font-mono text-xs';
      creaseDivider.style.display = 'flex';
      creaseDivider.className = 'h-6 bg-gradient-to-b from-slate-950 via-slate-700 to-slate-950 border-y border-slate-600 flex items-center justify-center relative cursor-row-resize';
      paneA.className = 'flex-1 bg-slate-800/90 rounded-xl p-3 flex flex-col justify-between border border-slate-700';
      paneB.className = 'flex-1 bg-slate-800/90 rounded-xl p-3 flex flex-col justify-between border border-slate-700';
      dimPaneA.textContent = `${schematic.clientWidth} x 120 px`;
      dimPaneB.textContent = `${schematic.clientWidth} x 120 px`;
    }
  }

  btnSimFlat.addEventListener('click', () => setSimMode('flat'));
  btnSimBook.addEventListener('click', () => setSimMode('book'));
  btnSimLaptop.addEventListener('click', () => setSimMode('laptop'));
  setSimMode('book');

  // 4. Crease Continuity Canvas Drag Test
  if (canvas) {
    const ctx = canvas.getContext('2d');
    let isDrawing = false;
    let points = [];
    let traversals = 0;
    let maxJump = 0;
    let lastPt = null;

    function resizeCanvas() {
      const rect = canvas.getBoundingClientRect();
      canvas.width = rect.width;
      canvas.height = rect.height;
      drawTraces();
    }
    resizeCanvas();
    window.addEventListener('resize', resizeCanvas);

    function drawTraces() {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      if (points.length < 2) return;

      ctx.lineWidth = 3;
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      for (let i = 1; i < points.length; i++) {
        const p0 = points[i - 1];
        const p1 = points[i];
        const dist = Math.sqrt((p1.x - p0.x) ** 2 + (p1.y - p0.y) ** 2);

        ctx.beginPath();
        ctx.moveTo(p0.x, p0.y);
        ctx.lineTo(p1.x, p1.y);
        ctx.strokeStyle = dist > 45 ? '#f43f5e' : '#38bdf8';
        ctx.stroke();
      }
    }

    function handlePointerDown(e) {
      isDrawing = true;
      const rect = canvas.getBoundingClientRect();
      const pt = { x: e.clientX - rect.left, y: e.clientY - rect.top, t: performance.now() };
      points.push(pt);
      lastPt = pt;
    }

    function handlePointerMove(e) {
      if (!isDrawing) return;
      const rect = canvas.getBoundingClientRect();
      const pt = { x: e.clientX - rect.left, y: e.clientY - rect.top, t: performance.now() };

      if (lastPt) {
        const dist = Math.sqrt((pt.x - lastPt.x) ** 2 + (pt.y - lastPt.y) ** 2);
        if (dist > maxJump) {
          maxJump = dist;
          statMaxJump.textContent = `${maxJump.toFixed(1)} px`;
        }

        const midX = canvas.width / 2;
        if ((lastPt.x < midX && pt.x >= midX) || (lastPt.x >= midX && pt.x < midX)) {
          traversals++;
          statTraversals.textContent = traversals;
        }

        // Update smoothness score
        const score = Math.max(0, Math.min(100, Math.round(100 - maxJump * 0.7)));
        valTouchScore.textContent = `${score}%`;
        valTouchSub.textContent = score > 80 ? 'Smooth continuous digitizer trace' : 'Coordinate jitter / dead zone detected';
      }

      points.push(pt);
      lastPt = pt;
      drawTraces();
    }

    function handlePointerUp() {
      isDrawing = false;
      lastPt = null;
    }

    canvas.addEventListener('pointerdown', handlePointerDown);
    canvas.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
    window.addEventListener('pointercancel', handlePointerUp);

    btnClear.addEventListener('click', () => {
      points = [];
      traversals = 0;
      maxJump = 0;
      statTraversals.textContent = '0';
      statMaxJump.textContent = '0.0 px';
      valTouchScore.textContent = '100%';
      valTouchSub.textContent = 'Zero dead-zone jumps detected';
      ctx.clearRect(0, 0, canvas.width, canvas.height);
    });
  }
});
